#!/usr/bin/env python

# Program for extracting the NES roms of each game in the Mega Man Legacy
# Collection for PC
# To use it, launch it in the same folder as Proteus.exe.

# NOTE: CybertKitsune figured out the password for data.pie which contains collection sounds and graphics.
# Extract it with 7-Zip and the password as follows:
# P091uWEdwe4lI6StDNMNlkodPGvJ38bL3HW6t3BCMYdFi83FXKu7k0NsHP8caDKS

# iNES Headers for Mega Man 1-6
HEADERS = [b'\x4E\x45\x53\x1A\x08\x00\x21\x00\x00\x00\x00\x00\x00\x00\x00\x00',
           b'\x4E\x45\x53\x1A\x10\x00\x10\x00\x00\x00\x00\x00\x00\x00\x00\x00',
           b'\x4E\x45\x53\x1A\x10\x10\x40\x00\x00\x00\x00\x00\x00\x00\x00\x00',
           b'\x4E\x45\x53\x1A\x20\x00\x40\x00\x00\x00\x00\x00\x00\x00\x00\x00',
           b'\x4E\x45\x53\x1A\x10\x20\x40\x00\x00\x00\x00\x00\x00\x00\x00\x00',
           b'\x4E\x45\x53\x1A\x20\x00\x40\x00\x00\x00\x00\x00\x00\x00\x00\x00']

# Offsets for each game's English ROM in the .exe file
# v1.1.1.29         OFFSET     SIZE             OFFSET      SIZE
OFFSETS = [{'PRG': [0x2AEEB0, 0x20000], 'CHA': None},
           {'PRG': [0x8ED70, 0x40000], 'CHA': None},
           {'PRG': [0xCEDB0, 0x40000], 'CHA': [0x10EDB0, 0x20000]},
           {'PRG': [0x12EDF0, 0x80000], 'CHA': None},
           {'PRG': [0x1AEE30, 0x40000], 'CHA': [0x1EEE30, 0x40000]},
           {'PRG': [0x22EE70, 0x80000], 'CHA': None}]

# Offsets for each game's Japanese ROM in the .exe file
# v1.1.1.29         OFFSET     SIZE             OFFSET      SIZE
JAPANOFFSETS = [{'PRG': [0x512230, 0x20000], 'CHA': None},
           {'PRG': [0x2F20F0, 0x40000], 'CHA': None},
           {'PRG': [0x332130, 0x40000], 'CHA': [0x372130, 0x20000]},
           {'PRG': [0x392170, 0x80000], 'CHA': None},
           {'PRG': [0x4121B0, 0x40000], 'CHA': [0x4521B0, 0x40000]},
           {'PRG': [0x4921F0, 0x80000], 'CHA': None}]

# In case the addresses above change in a new EXE build, search for these hex numbers:
# Mega Man 1 PRG - 00000000010101016268626969686869
# Mega Man 2 PRG - 00000000586058606060606060686068
# Mega Man 3 PRG - 9090909098909094949090B590909090
# Mega Man 3 CHA - 
# Mega Man 4 PRG - 
# Mega Man 5 PRG - A526C90ED009A5F9C90890034C9682A5
# Mega Man 5 CHA - 0304091F333F2C20000306011D130C0080E0F0F8F8F434140000E0F0F0F838180202070C0E1E1F1F00000007070F0C0E010103827C80808001010201837F7F7F80C0301838BCFCFC0000C0F0F07818381F0E0103071F3F3F0E00000101071F00FFFF1E08D5E3E3E37F7FFFF7E3C1C100FCB840E0F0FCFEFE380080C0C0F0FC00027979A37E3E0000
# Mega Man 6 PRG - 0000000000000000000000000000000000000000027979A3

if __name__ == '__main__':
    # Read in entire .exe file
    f = open("Proteus.exe", "rb")
    try:
        exe = f.read()
    finally:
        f.close()

    for i, game in enumerate(HEADERS):
        for section in ['PRG', 'CHA']:
            if OFFSETS[i][section]:
                start = OFFSETS[i][section][0]
                size = OFFSETS[i][section][1]
                end = start + size
                game += exe[start:end]
        out = open("Mega Man " + str(i+1) + " (U) (Legacy Collection).nes", "wb")
        try:
            out.write(game)
        finally:
            out.close()
    
    for i, game in enumerate(HEADERS):
        for section in ['PRG', 'CHA']:
            if JAPANOFFSETS[i][section]:
                start = JAPANOFFSETS[i][section][0]
                size = JAPANOFFSETS[i][section][1]
                end = start + size
                game += exe[start:end]
        # The Japanese versions are identical to the original Japanese cartridges.
        out = open("Rockman " + str(i+1) + " (J).nes", "wb")
        try:
            out.write(game)
        finally:
            out.close()
